-- Adicionar coluna status à tabela requisicoes
ALTER TABLE public.requisicoes 
ADD COLUMN status TEXT DEFAULT 'pendente' CHECK (status IN ('pendente', 'aprovada', 'rejeitada', 'em_pipeline'));

-- Adicionar índice para melhor performance
CREATE INDEX idx_requisicoes_status ON public.requisicoes(status);

-- Comentário explicativo
COMMENT ON COLUMN public.requisicoes.status IS 'Status da requisição: pendente, aprovada, rejeitada, em_pipeline';

-- Atualizar constraint de status para permitir 'em_fila'
ALTER TABLE public.requisicoes 
DROP CONSTRAINT IF EXISTS requisicoes_status_check;

ALTER TABLE public.requisicoes 
ADD CONSTRAINT requisicoes_status_check CHECK (
  status IN ('pendente', 'aprovada', 'rejeitada', 'em_pipeline', 'em_fila')
);

-- Comentário explicativo atualizado
COMMENT ON COLUMN public.requisicoes.status IS 'Status da requisição: pendente, aprovada, rejeitada, em_pipeline, em_fila';

-- Migration: Add manual category field to items tables
-- This allows users to manually set and preserve item categories

-- Add manual_category to requisicoes_itens
ALTER TABLE requisicoes_itens 
ADD COLUMN IF NOT EXISTS categoria_manual TEXT;

-- Add manual_category to active_session_items
ALTER TABLE active_session_items 
ADD COLUMN IF NOT EXISTS categoria_manual TEXT;

-- Add manual_category to digital_separation_items
ALTER TABLE digital_separation_items 
ADD COLUMN IF NOT EXISTS categoria_manual TEXT;

-- Add index for better query performance
CREATE INDEX IF NOT EXISTS idx_requisicoes_itens_categoria_manual 
ON requisicoes_itens(categoria_manual);

CREATE INDEX IF NOT EXISTS idx_active_session_items_categoria_manual 
ON active_session_items(categoria_manual);

CREATE INDEX IF NOT EXISTS idx_digital_separation_items_categoria_manual 
ON digital_separation_items(categoria_manual);

-- Add comment explaining the field
COMMENT ON COLUMN requisicoes_itens.categoria_manual IS 
'Categoria definida manualmente pelo usuário. Tem prioridade sobre a categoria detectada automaticamente.';

COMMENT ON COLUMN active_session_items.categoria_manual IS 
'Categoria definida manualmente pelo usuário. Tem prioridade sobre a categoria detectada automaticamente.';

COMMENT ON COLUMN digital_separation_items.categoria_manual IS 
'Categoria definida manualmente pelo usuário. Tem prioridade sobre a categoria detectada automaticamente.';

