1	-- DRP — Plano de Reposição
2	-- Adiciona idempotency_key em requisicoes + RPC drp_gerar_requisicoes (atomic, multi-loja).
3	--
4	-- Fluxo: frontend monta um payload com N planos (1 por loja) e chama esta função.
5	-- A função cria N requisicoes + M requisicoes_itens em UMA transação. Se idempotency_key
6	-- já existe, retorna o set existente sem duplicar (proteção contra double-click / retry).
7	
8	-- 1. Coluna idempotency_key
9	ALTER TABLE public.requisicoes
10	  ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
11	
12	-- Índice unique parcial: só linhas com idempotency_key não-nulo são únicas
13	CREATE UNIQUE INDEX IF NOT EXISTS idx_requisicoes_idempotency_key
14	  ON public.requisicoes (idempotency_key)
15	  WHERE idempotency_key IS NOT NULL;
16	
17	COMMENT ON COLUMN public.requisicoes.idempotency_key IS
18	  'Chave de idempotência usada por geradores em lote (ex: DRP). Linhas DRP usam hash(user_id, data_chegada, loja, plan_signature).';
19	
20	-- 2. RPC: drp_gerar_requisicoes
21	-- Input shape:
22	--   {
23	--     "data_chegada": "2026-05-08",          -- DATE — vai pra requisicoes.data_recebimento
24	--     "data_durar_ate": "2026-05-12",        -- DATE — só metadata na observacao
25	--     "user_name": "João",                   -- TEXT — usado como solicitante e em logs
26	--     "preparador": "Fábrica",               -- TEXT — sempre "Fábrica" em V1
27	--     "plans": [
28	--       {
29	--         "loja_id": 2,
30	--         "loja_nome": "Asa Sul",            -- TEXT — vai pra requisicoes.loja_solicitante
31	--         "idempotency_key": "drp:abc123",   -- TEXT — único por (user, data, loja, plan)
32	--         "items": [
33	--           { "produto_master_id": 123, "nome_produto": "Bolo Cenoura",
34	--             "quantidade_solicitada": 10, "ordem": 0,
35	--             "observacao": "DRP" }
36	--         ]
37	--       }
38	--     ]
39	--   }
40	--
41	-- Output:
42	--   {
43	--     "requisicoes": [
44	--       { "id": 4321, "loja_id": 2, "loja_nome": "Asa Sul",
45	--         "qtd_itens": 24, "qtd_unidades": 142, "idempotent_hit": false }
46	--     ]
47	--   }
