-- DRP — Plano de Reposição
-- Adiciona idempotency_key em requisicoes + RPC drp_gerar_requisicoes (atomic, multi-loja).
--
-- Fluxo: frontend monta um payload com N planos (1 por loja) e chama esta função.
-- A função cria N requisicoes + M requisicoes_itens em UMA transação. Se idempotency_key
-- já existe, retorna o set existente sem duplicar (proteção contra double-click / retry).

-- 1. Coluna idempotency_key
ALTER TABLE public.requisicoes
  ADD COLUMN IF NOT EXISTS idempotency_key TEXT;

-- Índice unique parcial: só linhas com idempotency_key não-nulo são únicas
CREATE UNIQUE INDEX IF NOT EXISTS idx_requisicoes_idempotency_key
  ON public.requisicoes (idempotency_key)
  WHERE idempotency_key IS NOT NULL;

COMMENT ON COLUMN public.requisicoes.idempotency_key IS
  'Chave de idempotência usada por geradores em lote (ex: DRP). Linhas DRP usam hash(user_id, data_chegada, loja, plan_signature).';

-- 2. RPC: drp_gerar_requisicoes
-- Input shape:
--   {
--     "data_chegada": "2026-05-08",          -- DATE — vai pra requisicoes.data_recebimento
--     "data_durar_ate": "2026-05-12",        -- DATE — só metadata na observacao
--     "user_name": "João",                   -- TEXT — usado como solicitante e em logs
--     "preparador": "Fábrica",               -- TEXT — sempre "Fábrica" em V1
--     "plans": [
--       {
--         "loja_id": 2,
--         "loja_nome": "Asa Sul",            -- TEXT — vai pra requisicoes.loja_solicitante
--         "idempotency_key": "drp:abc123",   -- TEXT — único por (user, data, loja, plan)
--         "items": [
--           { "produto_master_id": 123, "nome_produto": "Bolo Cenoura",
--             "quantidade_solicitada": 10, "ordem": 0,
--             "observacao": "DRP" }
--         ]
--       }
--     ]
--   }
--
-- Output:
--   {
--     "requisicoes": [
--       { "id": 4321, "loja_id": 2, "loja_nome": "Asa Sul",
--         "qtd_itens": 24, "qtd_unidades": 142, "idempotent_hit": false }
--     ]
--   }

CREATE OR REPLACE FUNCTION public.drp_gerar_requisicoes(plano JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_data_chegada DATE := (plano->>'data_chegada')::DATE;
  v_data_durar_ate DATE := (plano->>'data_durar_ate')::DATE;
  v_user_name TEXT := COALESCE(plano->>'user_name', 'Sistema');
  v_preparador TEXT := COALESCE(plano->>'preparador', 'Fábrica');
  v_plans JSONB := plano->'plans';
  v_plan JSONB;
  v_item JSONB;
  v_idem_key TEXT;
  v_loja_id INTEGER;
  v_loja_nome TEXT;
  v_existing_id INTEGER;
  v_new_req_id INTEGER;
  v_qtd_itens INTEGER;
  v_qtd_unidades INTEGER;
  v_results JSONB := '[]'::JSONB;
  v_result_item JSONB;
  v_obs TEXT;
  v_role_name TEXT;
BEGIN
  -- RBAC: só admin ou master
  SELECT ur.name INTO v_role_name
  FROM public.profiles p
  LEFT JOIN public.user_roles ur ON ur.id = p.role_id
  WHERE p.user_id = v_user_id;

  IF v_role_name IS NULL OR LOWER(v_role_name) NOT IN ('admin', 'administrador', 'master') THEN
    RAISE EXCEPTION 'drp_rbac_denied: apenas admin/master pode gerar requisições via DRP (role=%)', v_role_name
      USING ERRCODE = '42501';
  END IF;

  -- Validações estruturais
  IF v_data_chegada IS NULL THEN
    RAISE EXCEPTION 'drp_data_chegada_invalida' USING ERRCODE = '22023';
  END IF;
  IF v_data_durar_ate IS NULL THEN
    RAISE EXCEPTION 'drp_data_durar_ate_invalida' USING ERRCODE = '22023';
  END IF;
  IF (v_data_durar_ate - v_data_chegada) > 5 THEN
    RAISE EXCEPTION 'drp_horizonte_excede_validade: shelf-life uniforme 5d (chegada=%, durar_ate=%)',
      v_data_chegada, v_data_durar_ate USING ERRCODE = '22023';
  END IF;
  IF v_plans IS NULL OR jsonb_array_length(v_plans) = 0 THEN
    RAISE EXCEPTION 'drp_plans_vazio' USING ERRCODE = '22023';
  END IF;

  -- Itera sobre cada plano de loja
  FOR v_plan IN SELECT * FROM jsonb_array_elements(v_plans)
  LOOP
    v_loja_id := (v_plan->>'loja_id')::INTEGER;
    v_loja_nome := v_plan->>'loja_nome';
    v_idem_key := v_plan->>'idempotency_key';

    IF v_idem_key IS NULL OR length(v_idem_key) < 8 THEN
      RAISE EXCEPTION 'drp_idempotency_key_invalida (loja=%)', v_loja_nome USING ERRCODE = '22023';
    END IF;
    IF v_loja_nome IS NULL OR length(v_loja_nome) = 0 THEN
      RAISE EXCEPTION 'drp_loja_nome_invalida (loja_id=%)', v_loja_id USING ERRCODE = '22023';
    END IF;

    -- Idempotency check: já existe requisição com essa chave?
    SELECT id INTO v_existing_id
    FROM public.requisicoes
    WHERE idempotency_key = v_idem_key;

    IF v_existing_id IS NOT NULL THEN
      -- Já existe, retorna info dela
      SELECT
        COUNT(*)::INTEGER,
        COALESCE(SUM(quantidade_solicitada), 0)::INTEGER
      INTO v_qtd_itens, v_qtd_unidades
      FROM public.requisicoes_itens
      WHERE requisicao_id = v_existing_id;

      v_result_item := jsonb_build_object(
        'id', v_existing_id,
        'loja_id', v_loja_id,
        'loja_nome', v_loja_nome,
        'qtd_itens', v_qtd_itens,
        'qtd_unidades', v_qtd_unidades,
        'idempotent_hit', true
      );
      v_results := v_results || jsonb_build_array(v_result_item);
      CONTINUE;
    END IF;

    -- Cria a requisicao
    v_obs := format('Gerado via DRP — chegada=%s · durar_até=%s', v_data_chegada, v_data_durar_ate);
    INSERT INTO public.requisicoes (
      nome, solicitante, preparador,
      loja_solicitante, loja_preparadora,
      data_pedido, data_recebimento,
      user_id, status, idempotency_key
    )
    VALUES (
      format('DRP %s · %s', to_char(v_data_chegada, 'YYYY-MM-DD'), v_loja_nome),
      v_user_name,
      v_preparador,
      v_loja_nome,
      v_preparador,
      CURRENT_DATE,
      v_data_chegada,
      v_user_id,
      'em_fila',
      v_idem_key
    )
    RETURNING id INTO v_new_req_id;

    -- Cria os itens
    v_qtd_itens := 0;
    v_qtd_unidades := 0;
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_plan->'items')
    LOOP
      IF (v_item->>'quantidade_solicitada')::INTEGER <= 0 THEN
        CONTINUE; -- ignora itens com qty 0 (não cria linha vazia)
      END IF;

      INSERT INTO public.requisicoes_itens (
        requisicao_id, nome_produto,
        quantidade_solicitada, quantidade_enviada,
        observacao, ordem
      )
      VALUES (
        v_new_req_id,
        v_item->>'nome_produto',
        (v_item->>'quantidade_solicitada')::INTEGER,
        '',
        COALESCE(v_item->>'observacao', v_obs),
        COALESCE((v_item->>'ordem')::INTEGER, 0)
      );

      v_qtd_itens := v_qtd_itens + 1;
      v_qtd_unidades := v_qtd_unidades + (v_item->>'quantidade_solicitada')::INTEGER;
    END LOOP;

    -- Se nenhum item válido, rollback dessa requisição (evita req vazia)
    IF v_qtd_itens = 0 THEN
      DELETE FROM public.requisicoes WHERE id = v_new_req_id;
      CONTINUE;
    END IF;

    v_result_item := jsonb_build_object(
      'id', v_new_req_id,
      'loja_id', v_loja_id,
      'loja_nome', v_loja_nome,
      'qtd_itens', v_qtd_itens,
      'qtd_unidades', v_qtd_unidades,
      'idempotent_hit', false
    );
    v_results := v_results || jsonb_build_array(v_result_item);
  END LOOP;

  RETURN jsonb_build_object('requisicoes', v_results);
END;
$$;

-- Permissões
REVOKE ALL ON FUNCTION public.drp_gerar_requisicoes(JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.drp_gerar_requisicoes(JSONB) TO authenticated;

COMMENT ON FUNCTION public.drp_gerar_requisicoes(JSONB) IS
  'DRP — Cria N requisicoes + itens em transação atômica multi-loja. RBAC: admin/master. Idempotente via idempotency_key.';

-- Adiciona unidade_medida em requisicoes_itens para rastrear se item é cx, kg, litro, etc.
-- Padrão 'cx' mantém compatibilidade com registros existentes.
ALTER TABLE public.requisicoes_itens
  ADD COLUMN IF NOT EXISTS unidade_medida TEXT DEFAULT 'cx';

COMMENT ON COLUMN public.requisicoes_itens.unidade_medida IS
  'Unidade de medida do item. cx/caixa = cards individuais por quantidade. kg/g/l/ml = bulk (1 card para a qtd total).';

