import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { callLLM } from './llm.ts'
import { createTools, batchArray } from './tools.ts'
import { EdgeTracer, EdgeMetrics } from './telemetry.ts'

const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application, x-title, traceparent, tracestate',
}

function getWeekdaysArray(dayInput: string | string[]): number[] {
    const inputs = Array.isArray(dayInput) ? dayInput : [dayInput];
    if (!inputs || inputs.length === 0) return [new Date().getDay()];

    const map: Record<string, number> = {
        'domingo': 0, 'segunda': 1, 'segunda-feira': 1,
        'terça': 2, 'terça-feira': 2, 'terca': 2,
        'quarta': 3, 'quarta-feira': 3,
        'quinta': 4, 'quinta-feira': 4,
        'sexta': 5, 'sexta-feira': 5,
        'sábado': 6, 'sabado': 6
    };

    const uniqueDays = new Set(
        inputs
            .map(d => map[String(d).toLowerCase().trim()])
            .filter(d => d !== undefined)
    );

    const result = Array.from(uniqueDays).sort((a, b) => a - b);
    return result.length > 0 ? result : [new Date().getDay()];
}

serve(async (req: Request) => {
    if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })

    const tracer = new EdgeTracer(req);
    const metrics = new EdgeMetrics();

    try {
        const { store_id, products, target_days, target_date } = await req.json()

        if (!store_id || !products || !Array.isArray(products)) {
            throw new Error("Missing store_id or products array")
        }

        const supabase = createClient(
            Deno.env.get('SUPABASE_URL') ?? '',
            Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
        )

        const targetInput = target_days || target_date;
        const targetDayInts = getWeekdaysArray(targetInput);
        const dayNames = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
        const targetNames = targetDayInts.map(i => dayNames[i]).join(', ');

        // Span raiz — cobre toda a execução da Edge Function
        const rootSpan = tracer.startSpan('requisicao-automatica-ia');
        rootSpan.setAttribute('store_id', store_id);
        rootSpan.setAttribute('products_count', products.length);
        rootSpan.setAttribute('target_days', targetNames);
        rootSpan.setAttribute('trace_id', tracer.getTraceId());

        console.log(`[Scientific Agent V7] Orchestrator Started. Store ${store_id}, Targets: [${targetNames}], TraceID: ${tracer.getTraceId()}`);

        // --- STEP 1: MAP (Data Fetching) ---
        const mapSpan = tracer.startSpan('map-data-fetching', rootSpan.spanId);
        // Initialize Tools (now Data Fetchers)
        const toolsImplementation = createTools(supabase, store_id, products, targetDayInts);

        // Fetch Raw Data in Parallel (Deterministic)
        const [stockData, scientificData] = await Promise.all([
            toolsImplementation.fetchStockContext(),
            toolsImplementation.fetchSalesContext()
        ]);

        // Merge Data into a "Scientific Context Dossier"
        // We join on Product ID logic
        const fullContext = scientificData.map(metrics => {
            const stockInfo = stockData.find(s => s.id === metrics.id);
            const rawProduct = products.find((p: any) => p.id === metrics.id); // Original context if needed

            return {
                ...metrics,
                name: rawProduct?.name || metrics.name, // Ensure accurate name from payload
                code: rawProduct?.code || rawProduct?.codigo_interno || "", // Pass code through
                category: stockInfo?.category || "Outros",
                current_stock: stockInfo?.stock || 0
            };
        });

        mapSpan.setAttribute('context_items', fullContext.length);
        mapSpan.setAttribute('stock_items', stockData.length);
        mapSpan.setAttribute('scientific_items', scientificData.length);
        mapSpan.end();
        console.log(`[Map Phase] Context built for ${fullContext.length} items.`);

        // --- STEP 1.5: ANALYST LAYER (Hard Metrics Calculation) ---
        const analystSpan = tracer.startSpan('analyst-classification', rootSpan.spanId);
        // We classify items (ABC) and calculate hard metrics BEFORE the AI sees them.
        const getVolumeBasis = (item: any) => {
            const v = Number(item.forecast_total);
            if (Number.isFinite(v) && v > 0) return v;
            const fallback = Number(item.last_7d_avg);
            return Number.isFinite(fallback) ? fallback : 0;
        };

        const sortedByVolume = [...fullContext].sort((a, b) => getVolumeBasis(b) - getVolumeBasis(a));
        const totalVolume = sortedByVolume.reduce((sum, item) => sum + getVolumeBasis(item), 0);
        let accumulatedVolume = 0;

        // Re-map with Classification
        const itemClassMap = new Map<number, { classification: string, cumulativeRatio: number, shareRatio: number }>();
        sortedByVolume.forEach(item => {
            const basis = getVolumeBasis(item);
            accumulatedVolume += basis;
            const cumulativeRatio = accumulatedVolume / (totalVolume || 1);
            const shareRatio = basis / (totalVolume || 1);
            let classification = 'C';
            if (cumulativeRatio <= 0.8) classification = 'A'; // Top 80% volume = A
            else if (cumulativeRatio <= 0.95) classification = 'B'; // Next 15% = B
            else classification = 'C'; // Bottom 5% = C
            itemClassMap.set(item.id, { classification, cumulativeRatio, shareRatio });
        });

        const analystContext = fullContext.map(item => {
            const forecastTotal = Number(item.forecast_total) || 0;
            const avgPerSelectedDay = targetDayInts.length > 0 ? (forecastTotal / targetDayInts.length) : 0;
            const daysOfSupply = avgPerSelectedDay > 0 ? (item.current_stock / avgPerSelectedDay) : Number.POSITIVE_INFINITY;
            const classInfo = itemClassMap.get(item.id);
            const classification = classInfo?.classification || 'C';

            // Strategic Service Level Target
            const serviceLevelTarget = classification === 'A' ? 0.99 : (classification === 'B' ? 0.95 : 0.90);

            // Hard Math Suggestion (Baseline)
            const grossNeed = forecastTotal + (Number(item.safety_stock) || 0);
            const baseOrder = Math.max(0, Math.round(grossNeed - (Number(item.current_stock) || 0)));
            const isStockoutRisk = forecastTotal > 0 && (Number(item.current_stock) || 0) < forecastTotal;

            const sharePct = classInfo ? (classInfo.shareRatio * 100) : 0;
            const cumPct = classInfo ? (classInfo.cumulativeRatio * 100) : 0;
            const classReason = `Baseado na previsão dos dias selecionados: este item representa ~${sharePct.toFixed(1)}% do volume (acumulado ~${cumPct.toFixed(1)}%).`;

            return {
                ...item,
                abc_class: classification,
                class_reason: (classification === 'A'
                    ? `Classe A (Alta Importância). ${classReason}`
                    : (classification === 'B'
                        ? `Classe B (Importância Média). ${classReason}`
                        : `Classe C (Baixa Importância). ${classReason}`)),
                days_of_supply: daysOfSupply.toFixed(1),
                coverage_days_text: Number.isFinite(daysOfSupply) ? `${daysOfSupply.toFixed(1)} dias (no ritmo médio dos dias selecionados)` : 'Sem consumo histórico suficiente',
                service_level_target: `${(serviceLevelTarget * 100).toFixed(0)}%`,
                stockout_risk: isStockoutRisk ? "CRÍTICO (Vai faltar no ciclo selecionado)" : "BAIXO (Estoque cobre o ciclo selecionado)",
                base_order: baseOrder
            };
        });

        // Debug Stats
        const validSales = analystContext.filter(i => Number(i.forecast_total) > 0).length;
        const validStock = analystContext.filter(i => i.current_stock > 0).length;

        const classACnt = analystContext.filter(i => i.abc_class === 'A').length;
        const classBCnt = analystContext.filter(i => i.abc_class === 'B').length;
        const classCCnt = analystContext.filter(i => i.abc_class === 'C').length;
        analystSpan.setAttribute('items_with_forecast', validSales);
        analystSpan.setAttribute('items_with_stock', validStock);
        analystSpan.setAttribute('class_a_count', classACnt);
        analystSpan.setAttribute('class_b_count', classBCnt);
        analystSpan.setAttribute('class_c_count', classCCnt);
        analystSpan.end();

        console.log(`[Map Stats] Items with Forecast: ${validSales}, Items with Stock: ${validStock}`);

        if (validSales === 0) {
            console.warn(`[WARNING] No sales forecast found for any item! Check Store ID (${store_id}) or Match Status.`);
        }


        // --- STEP 2: PARTITION (Batching) ---
        // We chunk by 12 items to ensure deep reasoning within token limits
        // Optimal for "Deep Analysis" prompts
        // --- STEP 2: PARTITION (Batching) ---
        // We chunk by 6 items to ensure deep reasoning within token limits and avoid timeouts
        const BATCH_SIZE = 6;
        const batches = batchArray(analystContext, BATCH_SIZE);
        console.log(`[Partition Phase] Split into ${batches.length} batches.`);


        // --- STEP 3: WORKERS (Parallel Execution) ---
        const workersSpan = tracer.startSpan('workers-llm-analysis', rootSpan.spanId);
        workersSpan.setAttribute('batch_count', batches.length);
        workersSpan.setAttribute('batch_size', BATCH_SIZE);

        const processBatch = async (batchItems: any[], batchIndex: number) => {
            const batchSpan = tracer.startSpan(`worker-batch-${batchIndex}`, workersSpan.spanId);
            batchSpan.setAttribute('batch_index', batchIndex);
            batchSpan.setAttribute('items_count', batchItems.length);
            console.log(`[Worker ${batchIndex}] Analyzing ${batchItems.length} items...`);

            // Construct Granular Prompt
            const dossierText = batchItems.map(item => `
ITEM: ${item.name} (ID: ${item.id}${item.code ? `, CODE: ${item.code}` : ''})
Cat: ${item.category}
Classificação: ${item.abc_class} -> ${item.class_reason}
- Vendas previstas por dia (selecionados): ${item.forecast_days_text}
- DETALHAMENTO (risco por dia): ${item.daily_breakdown}
- Cobertura Atual: ${item.coverage_days_text} (Risco: ${item.stockout_risk})
- Meta Nível de Serviço: ${item.service_level_target}
- Previsão Total (${targetNames}): ${item.forecast_total}
- Estoque de Segurança (Buffer): ${item.safety_stock}
- Estoque Atual: ${item.current_stock}
- Volatilidade: ${item.volatility} | Tendência: ${item.trend}
- Conta Base (Total + Segurança - Estoque): ${item.base_order}
`).join('\n-------------------------------------------------\n');

            const SYSTEM_PROMPT = `
# PAPEL: Comitê Executivo de Supply Chain (Decisão Estratégica)
Você é um executivo sênior de supply chain, tomando decisões estratégicas para o ciclo: ${targetNames}.
O sistema já calculou a CONTA BASE corretamente (sem alucinação). Seu papel é agregar valor onde há trade-off e incerteza.
Use PORTUGUÊS DO BRASIL.

# REGRA CRÍTICA: ZERO ALUCINAÇÃO
- É PROIBIDO inventar estoque, vendas, dias, percentuais ou qualquer número.
- Você só pode devolver números em `delta_units` (inteiro). Todo o resto deve ser qualitativo e simples.

# O QUE VOCÊ DECIDE (onde está o valor da IA)
Você NÃO recalcula a matemática. Você escolhe um ajuste executivo em cima da conta base:
- `delta_units`: pode ser negativo (reduzir) ou positivo (aumentar).
- `confidence`: "alta" | "média" | "baixa".
- `flags`: lista curta (0-4) com sinais, por exemplo:
  - "pico_no_fim_de_semana", "volatilidade_alta", "tendencia_subindo", "tendencia_caindo", "historico_fraco", "risco_ruptura", "risco_excesso", "suspeita_mapping"
- `rationale_plain`: explicação para leigo, SEM NÚMEROS.

# HEURÍSTICAS EXECUTIVAS (exemplos)
- Classe A e risco de faltar: tender a proteger disponibilidade.
- Volatilidade alta + pico no sábado: adicionar buffer executivo.
- Conta base alta mas tendência caindo / risco de excesso: reduzir.
- Se histórico por dia for fraco/ausente: confiança baixa e pedir revisão humana.

# SAÍDA (APENAS JSON)
Retorne APENAS JSON no formato abaixo. Não inclua campos extras.
{
  "items": [
    {
      "id": 101,
      "delta_units": 3,
      "confidence": "média",
      "flags": ["pico_no_fim_de_semana", "volatilidade_alta", "risco_ruptura"],
      "rationale_plain": "Há risco de faltar nos dias mais fortes; prefiro proteger a disponibilidade com uma folga."
    },
    {
      "id": 102,
      "delta_units": -2,
      "confidence": "alta",
      "flags": ["risco_excesso"],
      "rationale_plain": "A conta base parece conservadora para este item; reduzir evita sobras e preserva caixa."
    }
  ]
}
`;
            const messages = [
                { role: 'system', content: SYSTEM_PROMPT },
                { role: 'user', content: `Analyze this batch:\n${dossierText}` }
            ];

            const processResponse = (responseContent: any) => {
                let content = responseContent.content.replace(/```json/g, '').replace(/```/g, '').trim();
                const parsed = JSON.parse(content);
                return Array.isArray(parsed.items) ? parsed.items : [];
            };

            const callWithTimeout = async (msgs: any[], model: string, timeoutMs: number) => {
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
                try {
                    const res = await callLLM(msgs, [], model, 0, controller.signal);
                    clearTimeout(timeoutId);
                    return res;
                } catch (err: any) {
                    clearTimeout(timeoutId);
                    throw err;
                }
            };

            try {
                // WORKER MODEL: User Requested Primary (with 25s Timeout)
                let response;
                try {
                    // Try Primary with strict timeout
                    const workerStart = Date.now();
                    response = await callWithTimeout(messages, "openai/gpt-oss-120b:free", 25000); // 25s
                    metrics.recordLlmCall({
                        model: response.model, provider: 'openrouter', operation: 'worker-batch',
                        inputTokens: response.usage.promptTokens, outputTokens: response.usage.completionTokens,
                        durationMs: Date.now() - workerStart,
                    });
                    batchSpan.setAttribute('model_used', response.model);
                    batchSpan.setAttribute('tokens.input', response.usage.promptTokens);
                    batchSpan.setAttribute('tokens.output', response.usage.completionTokens);
                    batchSpan.end();
                    return processResponse(response);
                } catch (primaryError: any) {
                    const isTimeout = primaryError.name === 'AbortError' || primaryError.message?.includes('aborted');
                    batchSpan.addEvent('primary_model_fallback', { reason: isTimeout ? 'timeout' : 'error' });
                    console.warn(`[Worker ${batchIndex}] Primary (${isTimeout ? 'TIMEOUT' : 'ERROR'}), fallback to Grok...`, isTimeout ? '' : primaryError);

                    // Fallback to Grok (Fast) - No strict timeout needed as it's the last resort, but let's be safe
                    const fallbackStart = Date.now();
                    response = await callLLM(messages, [], "x-ai/grok-4.1-fast");
                    metrics.recordLlmCall({
                        model: response.model, provider: 'openrouter', operation: 'worker-batch',
                        inputTokens: response.usage.promptTokens, outputTokens: response.usage.completionTokens,
                        durationMs: Date.now() - fallbackStart,
                    });
                    batchSpan.setAttribute('model_used', response.model);
                    batchSpan.setAttribute('tokens.input', response.usage.promptTokens);
                    batchSpan.setAttribute('tokens.output', response.usage.completionTokens);
                    batchSpan.end();
                    return processResponse(response);
                }
            } catch (e) {
                console.error(`[Worker ${batchIndex}] All Models Failed:`, e);
                batchSpan.setAttribute('model_used', 'fallback-math');
                batchSpan.endWithError(e instanceof Error ? e.message : 'All models failed');
                // Fallback to Math if LLM fails
                return batchItems.map(b => ({
                    id: b.id,
                    name: b.name,
                    delta_units: 0,
                    confidence: "baixa",
                    flags: ["falha_modelo"],
                    rationale_plain: "Falha no modelo; manter a conta base e revisar manualmente se necessário.",
                    category: b.category
                }));
            }
        };

        // Run Workers in Parallel with Concurrency Limit to avoid Timeouts/RateLimits
        // Increased to 10 to speed up execution for 7+ day queries
        const MAX_CONCURRENT = 10;
        const workerResults = [];
        for (let i = 0; i < batches.length; i += MAX_CONCURRENT) {
            const chunk = batches.slice(i, i + MAX_CONCURRENT);
            console.log(`[Orchestrator] Processing chunk ${i / MAX_CONCURRENT + 1} of ${Math.ceil(batches.length / MAX_CONCURRENT)}...`);
            const chunkResults = await Promise.all(
                chunk.map((batch, idx) => processBatch(batch, i + idx))
            );
            workerResults.push(...chunkResults);
        }

        workersSpan.setAttribute('total_results', workerResults.flat().length);
        workersSpan.end();

        // --- STEP 4: REDUCE (Merge) ---
        // Flatten results
        const allAnalyzedItems = workerResults.flat();

        const sanitizePlain = (text: any) => {
            const raw = String(text || '').trim();
            if (!raw) return '';
            return raw.replace(/[0-9]/g, '').replace(/\s+/g, ' ').trim();
        };

        const normalizeConfidence = (value: any): 'alta' | 'média' | 'baixa' => {
            const v = String(value || '').toLowerCase().trim();
            if (v === 'alta') return 'alta';
            if (v === 'media' || v === 'média') return 'média';
            if (v === 'baixa') return 'baixa';
            return 'média';
        };

        const normalizeFlags = (flags: any): string[] => {
            if (!Array.isArray(flags)) return [];
            const cleaned = flags
                .map(f => String(f || '').toLowerCase().trim())
                .filter(Boolean)
                .slice(0, 4);
            return Array.from(new Set(cleaned));
        };

        const getDeltaLimits = (abcClass: string, baseOrder: number) => {
            const base = Math.max(0, Math.round(baseOrder || 0));
            if (abcClass === 'A') {
                return { maxPositive: Math.max(6, Math.round(base * 0.5)), maxNegative: Math.min(base, Math.max(4, Math.round(base * 0.3))) };
            }
            if (abcClass === 'B') {
                return { maxPositive: Math.max(4, Math.round(base * 0.3)), maxNegative: Math.min(base, Math.max(3, Math.round(base * 0.5))) };
            }
            return { maxPositive: Math.max(2, Math.round(base * 0.15)), maxNegative: base };
        };

        // Group by Category for Final Output
        const finalCategoriesMap: Record<string, any[]> = {};
        const finalItemsEnriched: any[] = [];

        allAnalyzedItems.forEach((aiItem: any) => {
            const original = analystContext.find(f => f.id === aiItem.id) || fullContext.find(f => f.id === aiItem.id);
            const cat = original?.category || "Outros";
            const name = original?.name || aiItem.name;
            const code = original?.code;
            const currentStock = Number(original?.current_stock) || 0;
            const forecastTotal = Number(original?.forecast_total) || 0;
            const safetyStock = Number(original?.safety_stock) || 0;
            const baseOrder = Number(original?.base_order) || 0;

            const confidence = normalizeConfidence(aiItem.confidence);
            const flags = normalizeFlags(aiItem.flags);
            const rationalePlain = sanitizePlain(aiItem.rationale_plain ?? aiItem.justificativa ?? aiItem.observation);

            const deltaRaw = Number(aiItem.delta_units);
            const deltaUnits = Number.isFinite(deltaRaw) ? Math.round(deltaRaw) : 0;
            const limits = getDeltaLimits(String(original?.abc_class || ''), baseOrder);
            const clampedDelta = Math.max(-limits.maxNegative, Math.min(limits.maxPositive, deltaUnits));

            const requested = Math.max(0, Math.round(baseOrder) + clampedDelta);
            const deltaVsBase = requested - Math.round(baseOrder);
            const deltaClamped = clampedDelta !== deltaUnits;
            const forecastDaysText = original?.forecast_days_text || 'Sem histórico por dia selecionado';
            const observationParts = [
                `${original?.abc_class ? `Classe ${original.abc_class}. ` : ''}${original?.class_reason || ''}`.trim(),
                `Estoque atual: ${currentStock}.`,
                `Vendas previstas (${targetNames}): ${forecastDaysText}.`,
                `Segurança: ${Math.round(safetyStock)}.`,
                `Conta base: max(0, ${Math.round(forecastTotal)} + ${Math.round(safetyStock)} - ${currentStock}) = ${baseOrder}.`,
                `Decisão executiva: ${requested}${deltaVsBase !== 0 ? ` (${deltaVsBase > 0 ? `+${deltaVsBase}` : `${deltaVsBase}`} vs base)` : ''}.`,
                deltaClamped ? `Obs.: ajuste limitado pelo sistema (limites por classe).` : '',
                flags.length ? `Sinais: ${flags.join(', ')}.` : '',
                `Confiança: ${confidence}.`,
                rationalePlain ? `Motivo: ${rationalePlain}.` : ''
            ].filter(Boolean);

            const finalItem = {
                id: aiItem.id,
                name,
                code,
                requested,
                observation: observationParts.join(' '),
                category: cat,
                confidence,
                flags
            };

            if (!finalCategoriesMap[cat]) finalCategoriesMap[cat] = [];
            finalCategoriesMap[cat].push(finalItem);
            finalItemsEnriched.push(finalItem);
        });


        const finalCategories = Object.keys(finalCategoriesMap).map(cat => ({
            category: cat,
            items: finalCategoriesMap[cat]
        }));

        const responsePayload: any = {
            schema_version: "2",
            categories: finalCategories,
            items: finalItemsEnriched, // Added top-level items for Frontend compatibility
            meta: {
                total_items: finalItemsEnriched.length,
                total_requested: finalItemsEnriched.reduce((sum: any, i: any) => sum + (Number(i.requested) || 0), 0)
            }
        };


        console.log(`[Reduce Phase] Merged. Pre-Review Total: ${responsePayload.meta.total_requested}`);

        // --- STEP 4.5: HEALTH CHECK METRICS (Pre-Synthesizer) ---
        // Calculate "The Truth" before the VP sees it.
        const totalItemsCount = fullContext.length;
        const classAItems = analystContext.filter(i => i.abc_class === 'A');
        const criticalClassA = classAItems.filter(i => String(i.stockout_risk || '').startsWith('CRÍTICO'));

        // Check coverage in the final payload
        const coveredCriticalA = criticalClassA.filter(c => {
            const requestedItem = finalItemsEnriched.find(r => r.id === c.id);
            return (requestedItem && Number(requestedItem.requested) > 0);
        });

        const auditFindings: string[] = [];
        const confidenceCounts: Record<'alta' | 'média' | 'baixa', number> = { alta: 0, 'média': 0, baixa: 0 };
        const flagCounts: Record<string, number> = {};
        let clampedAdjustmentsCount = 0;
        finalItemsEnriched.forEach(item => {
            const original = analystContext.find(f => f.id === item.id);
            if (!original) return;

            const forecastTotal = Number(original.forecast_total) || 0;
            const currentStock = Number(original.current_stock) || 0;
            const baseOrder = Number(original.base_order) || 0;
            const requested = Number(item.requested) || 0;
            const confidence = String(item.confidence || '').toLowerCase().trim() as any;
            const flags: string[] = Array.isArray(item.flags) ? item.flags : [];

            if (confidence === 'alta' || confidence === 'média' || confidence === 'baixa') confidenceCounts[confidence] += 1;
            flags.forEach(f => { flagCounts[f] = (flagCounts[f] || 0) + 1; });

            const hasBreakdown = Array.isArray((original as any).forecast_by_day) ? (original as any).forecast_by_day.length > 0 : false;
            if (!hasBreakdown && forecastTotal > 0) {
                auditFindings.push(`Sem histórico por dia (usando média geral) em ${item.name} (ID ${item.id}).`);
            }

            if (forecastTotal > 0 && requested === 0 && currentStock < forecastTotal) {
                auditFindings.push(`Risco de falta: ${item.name} (ID ${item.id}) tem estoque abaixo do previsto e pedido zerado.`);
            }

            if (forecastTotal === 0 && requested > 0) {
                auditFindings.push(`Possível excesso: ${item.name} (ID ${item.id}) sem previsão no ciclo, mas com pedido > 0.`);
            }

            if (baseOrder > 0 && requested > (baseOrder * 2 + 5)) {
                auditFindings.push(`Desvio alto: ${item.name} (ID ${item.id}) pediu muito acima da conta base.`);
            }

            if (confidence === 'baixa') {
                auditFindings.push(`Confiança baixa: ${item.name} (ID ${item.id}) precisa revisão humana.`);
            }

            if (String(item.observation || '').includes('ajuste limitado pelo sistema')) {
                clampedAdjustmentsCount += 1;
                auditFindings.push(`Ajuste limitado: ${item.name} (ID ${item.id}) excedeu limites por classe.`);
            }
        });

        const topFlags = Object.entries(flagCounts)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 6)
            .map(([flag, count]) => `${flag} (${count})`);

        const healthMetrics = {
            total_skus: totalItemsCount,
            class_a_count: classAItems.length,
            critical_risk_count: criticalClassA.length,
            critical_risk_covered: coveredCriticalA.length,
            coverage_rate_critical: criticalClassA.length > 0 ? (coveredCriticalA.length / criticalClassA.length * 100).toFixed(0) + '%' : '100%',
            total_requested_volume: responsePayload.meta.total_requested,
            audit_findings_count: auditFindings.length,
            confidence_alta: confidenceCounts.alta,
            confidence_media: confidenceCounts['média'],
            confidence_baixa: confidenceCounts.baixa,
            clamped_adjustments: clampedAdjustmentsCount,
            top_flags: topFlags
        };

        // --- STEP 5: SYNTHESIZER REVIEW (DeepSeek R1 + Fallback) ---
        const synthSpan = tracer.startSpan('synthesizer-review', rootSpan.spanId);
        synthSpan.setAttribute('audit_findings_count', auditFindings.length);
        synthSpan.setAttribute('deterministic_verdict', deterministicVerdict);
        // Final Strategic Sanity Check (The "VP of Supply Chain" Role)
        console.log(`[Synthesizer] Starting Final Review...`);

        const deterministicVerdict = (() => {
            if (healthMetrics.critical_risk_count > 0 && healthMetrics.critical_risk_covered < healthMetrics.critical_risk_count) return 'CRÍTICO';
            if (auditFindings.length > 0) return 'ATENÇÃO';
            return 'APROVADO';
        })();

        const deterministicReview = [
            `VEREDITO: ${deterministicVerdict}`,
            `ANÁLISE: Cobertura Classe A em risco: ${healthMetrics.critical_risk_covered}/${healthMetrics.critical_risk_count} (${healthMetrics.coverage_rate_critical}). Confiança (alta/média/baixa): ${healthMetrics.confidence_alta}/${healthMetrics.confidence_media}/${healthMetrics.confidence_baixa}. Alertas: ${auditFindings.length}.`,
            healthMetrics.top_flags.length ? `SINAIS: ${healthMetrics.top_flags.join(', ')}.` : '',
            auditFindings.length > 0 ? `AÇÃO: Revisar itens/alertas: ${auditFindings.slice(0, 4).join(' ')}` : 'AÇÃO: Pode prosseguir com a revisão.'
        ].filter(Boolean).join('\n');

        const REVIEW_PROMPT = `
# PAPEL: Vice-Presidente de Supply Chain (Auditor Final)
Você é a autoridade máxima de logística da empresa.
Sua função é auditar o trabalho dos "Gerentes de Produto" (Workers) e emitir um parecer final para a diretoria humana.

# CONTEXTO DA AUDITORIA
- Loja: ${store_id}
- Ciclo de Abastecimento: ${targetNames} (${targetDayInts.length} dias)
- Total de SKUs Analisados: ${healthMetrics.total_skus}

# RELATÓRIO DE SAÚDE DO PEDIDO (Health Check)
- Itens Classe A (Ouro): ${healthMetrics.class_a_count}
- Risco Crítico de Ruptura (Classe A): ${healthMetrics.critical_risk_count} itens.
- Cobertura de Risco Crítico Realizada: ${healthMetrics.critical_risk_covered} itens (${healthMetrics.coverage_rate_critical}).
- Volume Total Solicitado: ${healthMetrics.total_requested_volume} unidades.
- Alertas objetivos detectados pelo sistema: ${healthMetrics.audit_findings_count}.
- Confiança (alta/média/baixa): ${healthMetrics.confidence_alta}/${healthMetrics.confidence_media}/${healthMetrics.confidence_baixa}.
- Ajustes limitados pelo sistema: ${healthMetrics.clamped_adjustments}.
- Sinais mais comuns: ${healthMetrics.top_flags.join(', ') || 'nenhum'}.

# ALERTAS (SE EXISTIREM)
${auditFindings.slice(0, 8).map(a => `- ${a}`).join('\n')}

# SUA TAREFA
Analise esses dados e emita um **Parecer Executivo** em PORTUGUÊS DO BRASIL.
Você deve validar se a estratégia de "Proteção de Ruptura" foi seguida.

# FORMATO DE SAÍDA (APENAS JSON)
Retorne:
{
  "veredito": "APROVADO | ATENÇÃO | CRÍTICO",
  "analise": "texto curto",
  "acao": "texto curto"
}
`;

        let synthesizerReview = "";
        try {
            // SYNTHESIZER MODEL: Deep Reasoning (DeepSeek)
            console.log("[Synthesizer] Trying Primary (DeepSeek)...");
            const reviewMessages = [
                { role: 'system', content: REVIEW_PROMPT },
                { role: 'user', content: "Analyze logic." }
            ];

            const callWithTimeout = async (msgs: any[], model: string, timeoutMs: number) => {
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
                try {
                    const res = await callLLM(msgs, [], model, 0, controller.signal);
                    clearTimeout(timeoutId);
                    return res;
                } catch (err: any) {
                    clearTimeout(timeoutId);
                    throw err;
                }
            };

            let reviewResponse;
            try {
                // Try DeepSeek with 45s Timeout (it is slow, give it a chance, but dont die)
                const synthStart = Date.now();
                reviewResponse = await callWithTimeout(reviewMessages, "deepseek/deepseek-r1-0528:free", 45000);
                metrics.recordLlmCall({
                    model: reviewResponse.model, provider: 'openrouter', operation: 'synthesizer-review',
                    inputTokens: reviewResponse.usage.promptTokens, outputTokens: reviewResponse.usage.completionTokens,
                    durationMs: Date.now() - synthStart,
                });
                synthSpan.setAttribute('model_used', reviewResponse.model);
                synthSpan.setAttribute('tokens.input', reviewResponse.usage.promptTokens);
                synthSpan.setAttribute('tokens.output', reviewResponse.usage.completionTokens);
            } catch (primaryErr: any) {
                const isTimeout = primaryErr.name === 'AbortError' || primaryErr.message?.includes('aborted');
                synthSpan.addEvent('primary_model_fallback', { reason: isTimeout ? 'timeout' : 'error' });
                console.warn(`[Synthesizer] Primary (${isTimeout ? 'TIMEOUT' : 'ERROR'}), fallback to Grok...`);
                const fallbackStart = Date.now();
                reviewResponse = await callLLM(reviewMessages, [], "x-ai/grok-4.1-fast");
                metrics.recordLlmCall({
                    model: reviewResponse.model, provider: 'openrouter', operation: 'synthesizer-review',
                    inputTokens: reviewResponse.usage.promptTokens, outputTokens: reviewResponse.usage.completionTokens,
                    durationMs: Date.now() - fallbackStart,
                });
                synthSpan.setAttribute('model_used', reviewResponse.model);
                synthSpan.setAttribute('tokens.input', reviewResponse.usage.promptTokens);
                synthSpan.setAttribute('tokens.output', reviewResponse.usage.completionTokens);
            }

            try {
                const parsed = JSON.parse(String(reviewResponse.content || '').trim());
                const veredito = String(parsed.veredito || '').toUpperCase().trim();
                const analise = String(parsed.analise || '').trim();
                const acao = String(parsed.acao || '').trim();
                const parts = [
                    `VEREDITO: ${veredito || deterministicVerdict}`,
                    `ANÁLISE: ${analise || `Cobertura Classe A em risco: ${healthMetrics.critical_risk_covered}/${healthMetrics.critical_risk_count} (${healthMetrics.coverage_rate_critical}). Confiança baixa: ${healthMetrics.confidence_baixa}.`}`,
                    `AÇÃO: ${acao || (auditFindings.length > 0 ? 'Revisar alertas listados antes de aprovar.' : 'Pode prosseguir com a revisão.')}`
                ];
                synthesizerReview = parts.join('\n').slice(0, 500);
                synthSpan.setAttribute('veredito', veredito || deterministicVerdict);
                synthSpan.end();
            } catch {
                synthesizerReview = deterministicReview.slice(0, 500);
                synthSpan.setAttribute('veredito', deterministicVerdict);
                synthSpan.end();
            }

        } catch (e) {
            console.error("[Synthesizer] Review Failed (Both models).", e);
            synthesizerReview = deterministicReview.slice(0, 500);
            synthSpan.endWithError(e instanceof Error ? e.message : 'Synthesizer review failed');
        }

        // REORDER RESPONSE: META FIRST
        const finalResponse = {
            meta: {
                ...responsePayload.meta,
                synthesizer_review: synthesizerReview,
                audit_findings: auditFindings.slice(0, 12),
                execution_time_ms: Date.now(),
                trace_id: tracer.getTraceId()
            },
            items: finalItemsEnriched, // Top level items
            categories: finalCategories,
            schema_version: "3"
        };

        rootSpan.setAttribute('total_items', finalItemsEnriched.length);
        rootSpan.setAttribute('total_requested', finalResponse.meta.total_requested);
        rootSpan.end();

        // Exportar spans e métricas (fire-and-forget — não bloqueia a resposta)
        tracer.flush().catch(() => {});
        metrics.flush().catch(() => {});

        return new Response(JSON.stringify(finalResponse), {
            headers: {
                ...corsHeaders,
                'Content-Type': 'application/json',
                'traceparent': tracer.getResponseTraceparent(),
            },
        })

    } catch (error: any) {
        console.error("Function Error:", error.message)

        // Exportar spans e métricas mesmo em caso de erro
        tracer.flush().catch(() => {});
        metrics.flush().catch(() => {});

        return new Response(JSON.stringify({ error: error.message }), {
            headers: {
                ...corsHeaders,
                'Content-Type': 'application/json',
                'traceparent': tracer.getResponseTraceparent(),
            },
            status: 400,
        })
    }
})

