// Função para carregar histórico do banco de dados
const loadHistoryFromDatabase = async () => {
  try {
    const { data: authData } = await supabase.auth.getUser();
    const currentUserId = authData?.user?.id || null;

    let query = (supabase as any)
      .from('requisicoes')
      .select(`
        id,
        nome,
        solicitante,
        preparador,
        loja_solicitante,
        loja_preparadora,
        data_pedido,
        data_recebimento,
        created_at,
        enqueued_at,
        status,
        subtitle,
        requisicoes_itens (
          id,
          nome_produto,
          quantidade_solicitada,
          quantidade_enviada,
          observacao,
          ordem,
          category
        )
      `)
      .order('created_at', { ascending: false });

    if (currentUserId) {
      query = query.eq('user_id', currentUserId);
    }

    const { data: requisicoes, error } = await query as any;

    if (error) {
      handleError(error, { domain: 'requisicoes', operation: 'carregarHistorico', showToast: false });
      toast.error('Erro ao carregar histórico de requisições');
      return;
    }

    const formattedLists = (requisicoes || []).map(req => ({
      id: req.id,
      name: req.nome,
      createdAt: req.created_at,
      enqueuedAt: req.enqueued_at,
      requesterName: req.solicitante,
      preparerName: req.preparador,
      storeRequester: req.loja_solicitante,
      storePreparer: req.loja_preparadora,
      orderDate: req.data_pedido,
      receivedDate: req.data_recebimento,
      status: req.status,
      subtitle: req.subtitle,
      items: (req.requisicoes_itens || []).map(item => ({
        id: item.id.toString(),
        name: item.nome_produto,
        requested: item.quantidade_solicitada,
        sent: item.quantidade_enviada,
        observation: item.observacao || '',
        category: item.category || detectCategory(item.nome_produto)
      }))
    }));

    setSavedLists(formattedLists);
  } catch (error) {
    handleError(error, { domain: 'requisicoes', operation: 'carregarHistorico', showToast: false });
    toast.error('Erro ao carregar histórico de requisições');
  }
};

