const saveEditsForExistingRequisicao = async (): Promise<boolean> => {
  if (!currentRequisicaoId) return false;
  if (isSavingList) return false;
  if (allItems.length === 0) { toast.error('Não há itens para salvar'); return false; }
  const normalizedRequesterValue = normalizeStoreName(storeRequester) || storeRequester;
  const normalizedPreparerValue = normalizeStoreName(storePreparer) || storePreparer;
  const lojaSolicitante = getStoreLabel(normalizedRequesterValue);
  const lojaPreparadora = getStoreLabel(normalizedPreparerValue) || 'Fábrica';
  const orderDateToSave = coerceISODateString(orderDate);
  const receivedDateToSave = coerceISODateString(receivedDate);
  if (receivedDateToSave) {
    if (!validateDeliveryDate(orderDateToSave, receivedDateToSave)) {
      toast.error('❌ Data de entrega não pode ser anterior à data do pedido');
      return;
    }
  }
  try {
    setIsSavingList(true);
    const { data: { user } } = await supabase.auth.getUser();
    const currentUserId = user?.id || null;
    const { error: updateError } = await (supabase as any)
      .from('requisicoes')
      .update({
        solicitante: requesterName,
        preparador: preparerName,
        loja_solicitante: lojaSolicitante,
        loja_preparadora: lojaPreparadora,
        data_pedido: orderDateToSave,
        data_recebimento: receivedDateToSave,
        status: currentRequisicaoStatus || 'em_fila',
        user_id: currentUserId,
        subtitle: requisitionSubtitle
      })
      .eq('id', Number(currentRequisicaoId));

    if (updateError) {
      handleError(updateError, { domain: 'requisicoes', operation: 'salvarAlteracoesRequisicao', showToast: false });
      toast.error('Erro ao salvar alterações');
      return false;
    }

    const { data: existingDbItems } = await (supabase as any)
      .from('requisicoes_itens')
      .select('id')
      .eq('requisicao_id', Number(currentRequisicaoId));

    const existingIds = new Set<number>((existingDbItems || []).map((x: any) => Number(x.id)).filter((n) => Number.isFinite(n)));

    const itemsWithId = allItems
      .map((it, index) => ({
        idNum: Number(it.id),
        nome: String(it.name || '').trim(),
        solicitada: Number.isFinite(Number(it.requested)) ? Number(it.requested) : 0,
        enviada: String(it.sent ?? '').trim(),
        obs: String(it.observation || '').trim(),
        ordem: Number.isFinite(index) ? index : 0,
        categoria: getEffectiveCategory(it.manualCategory, it.category, String(it.name || '')) || detectCategory(String(it.name || ''))
      }))
      .filter((x) => Number.isFinite(x.idNum) && x.nome);

    for (const x of itemsWithId) {
      await (supabase as any)
        .from('requisicoes_itens')
        .update({
          nome_produto: x.nome,
          quantidade_solicitada: x.solicitada,
          quantidade_enviada: x.enviada,
          observacao: x.obs,
          ordem: x.ordem,
          category: x.categoria
        })
        .eq('id', x.idNum);
    }

    const newItems = allItems
      .map((it, index) => ({
        idStr: String(it.id || ''),
        nome: String(it.name || '').trim(),
        solicitada: Number.isFinite(Number(it.requested)) ? Number(it.requested) : 0,
        enviada: String(it.sent ?? '').trim(),
        obs: String(it.observation || '').trim(),
        ordem: Number.isFinite(index) ? index : 0,
        categoria: getEffectiveCategory(it.manualCategory, it.category, String(it.name || '')) || detectCategory(String(it.name || ''))
      }))
      .filter((x) => x.idStr.startsWith('temp-') && x.nome);

    for (const x of newItems) {
      const { data: inserted } = await (supabase as any)
        .from('requisicoes_itens')
        .upsert({
          requisicao_id: Number(currentRequisicaoId),
          nome_produto: x.nome,
          quantidade_solicitada: x.solicitada,
          quantidade_enviada: x.enviada,
          observacao: x.obs,
          ordem: x.ordem,
          category: x.categoria
        }, { onConflict: 'requisicao_id,nome_produto' })
        .select('id')
        .single();
      if (inserted?.id) {
        setAllItems((prev) => prev.map((i) => String(i.id || '').startsWith('temp-') && String(i.name || '').trim() === x.nome ? { ...i, id: String(inserted.id) } : i));
      }
    }

    const keepIds = new Set<number>(itemsWithId.map((x) => x.idNum));
    const toDelete = Array.from(existingIds).filter((id) => !keepIds.has(id));
    if (toDelete.length) {
      await (supabase as any)
        .from('requisicoes_itens')
        .delete()
        .in('id', toDelete);
    }

    await loadHistoryFromDatabase();
    toast.success('Pedido atualizado');
    return true;
  } catch (error) {
    handleError(error, { domain: 'requisicoes', operation: 'salvarAlteracoes', showToast: false });
    toast.error('Erro ao salvar alterações');
    return false;
  } finally {
    setIsSavingList(false);
  }
};

