  return;
}
if (!orderDate || !orderDate.toString().trim()) {
  toast.error('Defina a Data do Pedido');
  return;
}
if (!receivedDate || !receivedDate.toString().trim()) {
  toast.error('Defina a Data de Recebimento');
  return;
}
// Não validar nome da lista: é gerado automaticamente a partir da loja e data

try {
  setIsSavingList(true);
  const normalizedPreparerValue = normalizeStoreName('Fábrica');
  const lojaPreparadora = getStoreLabel(normalizedPreparerValue) || 'Fábrica';
  const orderDateToSave = coerceISODateString(orderDate);
  const receivedDateToSave = coerceISODateString(receivedDate);

  // Valida somente se houver data de recebido; se vazio, permite salvar sem recebido
  if (receivedDateToSave) {
    if (!validateDeliveryDate(orderDateToSave, receivedDateToSave)) {
      toast.error('❌ Data de entrega não pode ser anterior à data do pedido');
      return;
    }
  }

  const itensSanitizados = allItems
    .map((item, index) => {
      const nome = String(item.name || '').trim();
      if (!nome) return null;
      const solicitadaRaw = item.requested;
      const solicitada = Number.isFinite(Number(solicitadaRaw)) ? Number(solicitadaRaw) : 0;
      const enviada = String(item.sent ?? '').trim();
      const obs = String(item.observation || '');
      const ordem = Number.isFinite(index) ? index : 0;
      const categoriaEfetiva = getEffectiveCategory(item.manualCategory, item.category, nome) || detectCategory(nome);
      return {
        nome_produto: nome,
        quantidade_solicitada: solicitada,
        quantidade_enviada: enviada,
        observacao: obs,
        ordem,
        category: categoriaEfetiva,
        produto_id: item.matchedId ? Number(item.matchedId) : null,
        codigo_interno: item.code || null,
        // RPC faz COALESCE pra 'cx' quando vazio.
        unidade_medida: item.unidade_medida || null,
      };
    })
    .filter((v) => v !== null);

  if (!itensSanitizados || itensSanitizados.length === 0) {
    toast.error('Nenhum item válido para salvar');
    return;
  }

  const { data: newId, error: rpcError } = await (supabase as any).rpc('save_requisicao_and_items', {
    p_nome: listName,
    p_solicitante: requesterName,
    p_preparador: preparerName,
    p_loja_solicitante: lojaSolicitante,
    p_loja_preparadora: lojaPreparadora,
    p_data_pedido: orderDateToSave,
    p_data_recebimento: receivedDateToSave || null,
    p_status: 'em_fila',
    p_itens: itensSanitizados,
    p_existing_id: currentRequisicaoId ? Number(currentRequisicaoId) : null,

