if (reqError) {
  handleError(reqError, { domain: 'requisicoes', operation: 'salvarRequisicao', showToast: false });
  toast.error('Erro ao salvar requisição');
  return;
}

// Sanitizar e AGRUPAR itens por produto para respeitar a unique constraint
// Estratégia: somar "quantidade_solicitada" de duplicados e concatenar observações.
const itensSanitizadosRaw = allItems
  .map((item, index) => {
    const nomeOriginal = String(item.name || '').trim();
    if (!nomeOriginal) return null; // Ignorar itens sem nome
    const chave = nomeOriginal.toLowerCase(); // chave de agrupamento case-insensitive
    const solicitadaRaw = item.requested;
    const solicitada = Number.isFinite(Number(solicitadaRaw)) ? Number(solicitadaRaw) : 0;

    // Filter out "Ghost Items" (0 quantity) from valid submission
    if (solicitada <= 0) return null;

    const enviada = String(item.sent ?? '').trim();
    const obs = String(item.observation || '').trim();
    const ordem = Number.isFinite(index) ? index : 0;
    const categoriaEfetiva = getEffectiveCategory(item.manualCategory, item.category, nomeOriginal) || detectCategory(nomeOriginal);
    return {
      requisicao_id: requisicao.id,
      chave,
      nome_produto: nomeOriginal,
      quantidade_solicitada: solicitada,
      quantidade_enviada: enviada,
      observacao: obs,
      ordem,
      category: categoriaEfetiva,
      produto_id: item.matchedId ? Number(item.matchedId) : null,
      codigo_interno: item.code || null
    };
  })
  .filter((v) => v !== null) as Array<{
    requisicao_id: number;
    chave: string;
    nome_produto: string;
    quantidade_solicitada: number;
    quantidade_enviada: string;
    observacao: string;
    ordem: number;
    category: string;
    produto_id: number | null;
    codigo_interno: string | null;
  }>;

if (itensSanitizadosRaw.length === 0) {
  toast.error('Nenhum item válido para enviar');
  return;
}

// Agrupar por "chave" e mesclar dados
const agrupadosMap = new Map<string, {
  requisicao_id: number;
  nome_produto: string;
  quantidade_solicitada: number;
  quantidade_enviada: string;
  observacao: string;
  ordem: number;
  category?: string;
  produto_id?: number | null;
  codigo_interno?: string | null;
}>();

for (const it of itensSanitizadosRaw) {
  const existente = agrupadosMap.get(it.chave);
  if (!existente) {
    agrupadosMap.set(it.chave, {
      requisicao_id: it.requisicao_id,
      nome_produto: it.nome_produto,
      quantidade_solicitada: it.quantidade_solicitada,
      quantidade_enviada: it.quantidade_enviada,
      observacao: it.observacao,
      ordem: it.ordem,
      category: it.category,
      produto_id: it.produto_id,
      codigo_interno: it.codigo_interno
    });
  } else {
    existente.quantidade_solicitada += it.quantidade_solicitada;
    // manter quantidade_enviada mais recente não vazia
    if (it.quantidade_enviada) existente.quantidade_enviada = it.quantidade_enviada;
    // concatenar observações se houver
    if (it.observacao) {
      existente.observacao = existente.observacao
        ? `${existente.observacao}; ${it.observacao}`
        : it.observacao;
    }
    // manter a menor ordem (primeira aparição) para estabilidade visual
    existente.ordem = Math.min(existente.ordem, it.ordem);
    if (!existente.category && it.category) existente.category = it.category;
    if (!existente.produto_id && it.produto_id) existente.produto_id = it.produto_id;
  }
}

const itensSanitizados = Array.from(agrupadosMap.values());

if (itensSanitizados.length === 0) {
  toast.error('Nenhum item válido para enviar');
  return;
}

// Usar UPSERT para respeitar a unique constraint (requisicao_id, nome_produto)
const { error: itensError } = await (supabase as any)
  .from('requisicoes_itens')
  .upsert(itensSanitizados, { onConflict: 'requisicao_id,nome_produto' });

if (itensError) {
  wideError('requisicao.salvar_itens_lote_erro', 'Erro ao salvar itens em lote', { domain: 'requisicoes', attributes: {
    code: (itensError as any)?.code,
    details: (itensError as any)?.details,
    message: (itensError as any)?.message
  } });
  // Fallback: upsert item a item para que ao menos parte dos itens entre na fila
  let inseridos = 0;
  for (const it of itensSanitizados) {
    const { error: oneErr } = await (supabase as any)
      .from('requisicoes_itens')
      .upsert(it, { onConflict: 'requisicao_id,nome_produto' });
    if (oneErr) {
      wideWarn('requisicao.item_erro_inserir', `Ignorando item com erro ao inserir: ${it.nome_produto}`, { domain: 'requisicoes', attributes: {
        nomeProduto: it.nome_produto,
        code: (oneErr as any)?.code,
        details: (oneErr as any)?.details,
        message: (oneErr as any)?.message
      } });
      continue;

