1	-- ===========================================================================
2	-- Propaga unidade_medida no fluxo de requisição:
3	--   1. save_requisicao_and_items aceita unidade_medida por item
4	--   2. active_session_items ganha unidade_medida (separação digital)
5	-- ===========================================================================
6	
7	-- 1. active_session_items: coluna nova com default 'cx' (compat existentes)
8	ALTER TABLE public.active_session_items
9	  ADD COLUMN IF NOT EXISTS unidade_medida TEXT DEFAULT 'cx';
10	
11	COMMENT ON COLUMN public.active_session_items.unidade_medida IS
12	  'Unidade do item na sessão de separação. Default cx mantém comportamento legado.';
13	
14	-- 2. RPC: aceita unidade_medida em cada item do array JSONB
15	CREATE OR REPLACE FUNCTION public.save_requisicao_and_items(
16	  p_nome text,
17	  p_solicitante text,
18	  p_preparador text,
19	  p_loja_solicitante text,
20	  p_loja_preparadora text,
21	  p_data_pedido text,
22	  p_data_recebimento text,
23	  p_status text,
24	  p_itens jsonb,
25	  p_existing_id integer DEFAULT NULL::integer,
26	  p_subtitle text DEFAULT NULL::text
27	)
28	RETURNS integer
29	LANGUAGE plpgsql
30	AS $function$
31	DECLARE
32	  v_requisicao_id INTEGER;
33	  v_item JSONB;
34	  v_nome TEXT;
35	  v_qtd_solicitada INTEGER;
36	  v_qtd_enviada TEXT;
37	  v_obs TEXT;
38	  v_ordem INTEGER;
39	  v_category TEXT;
40	  v_produto_id INTEGER;
41	  v_unidade TEXT;
42	BEGIN
43	  IF p_existing_id IS NOT NULL THEN
44	    UPDATE public.requisicoes
45	      SET nome = p_nome,
46	          solicitante = p_solicitante,
47	          preparador = p_preparador,
48	          loja_solicitante = p_loja_solicitante,
49	          loja_preparadora = p_loja_preparadora,
50	          data_pedido = p_data_pedido,
51	          data_recebimento = p_data_recebimento,
52	          status = COALESCE(p_status, 'pendente'),
53	          subtitle = p_subtitle,
54	          updated_at = NOW()
55	    WHERE id = p_existing_id
56	    RETURNING id INTO v_requisicao_id;
57	
58	    IF v_requisicao_id IS NULL THEN
59	      INSERT INTO public.requisicoes (
60	        nome, solicitante, preparador, loja_solicitante, loja_preparadora,
61	        data_pedido, data_recebimento, status, subtitle
62	      ) VALUES (
63	        p_nome, p_solicitante, p_preparador, p_loja_solicitante, p_loja_preparadora,
64	        p_data_pedido, p_data_recebimento, COALESCE(p_status, 'pendente'), p_subtitle
65	      ) RETURNING id INTO v_requisicao_id;
66	    ELSE
67	      DELETE FROM public.requisicoes_itens WHERE requisicao_id = v_requisicao_id;
68	    END IF;
69	  ELSE
