-- ===========================================================================
-- Propaga unidade_medida no fluxo de requisição:
--   1. save_requisicao_and_items aceita unidade_medida por item
--   2. active_session_items ganha unidade_medida (separação digital)
-- ===========================================================================

-- 1. active_session_items: coluna nova com default 'cx' (compat existentes)
ALTER TABLE public.active_session_items
  ADD COLUMN IF NOT EXISTS unidade_medida TEXT DEFAULT 'cx';

COMMENT ON COLUMN public.active_session_items.unidade_medida IS
  'Unidade do item na sessão de separação. Default cx mantém comportamento legado.';

-- 2. RPC: aceita unidade_medida em cada item do array JSONB
CREATE OR REPLACE FUNCTION public.save_requisicao_and_items(
  p_nome text,
  p_solicitante text,
  p_preparador text,
  p_loja_solicitante text,
  p_loja_preparadora text,
  p_data_pedido text,
  p_data_recebimento text,
  p_status text,
  p_itens jsonb,
  p_existing_id integer DEFAULT NULL::integer,
  p_subtitle text DEFAULT NULL::text
)
RETURNS integer
LANGUAGE plpgsql
AS $function$
DECLARE
  v_requisicao_id INTEGER;
  v_item JSONB;
  v_nome TEXT;
  v_qtd_solicitada INTEGER;
  v_qtd_enviada TEXT;
  v_obs TEXT;
  v_ordem INTEGER;
  v_category TEXT;
  v_produto_id INTEGER;
  v_unidade TEXT;
BEGIN
  IF p_existing_id IS NOT NULL THEN
    UPDATE public.requisicoes
      SET nome = p_nome,
          solicitante = p_solicitante,
          preparador = p_preparador,
          loja_solicitante = p_loja_solicitante,
          loja_preparadora = p_loja_preparadora,
          data_pedido = p_data_pedido,
          data_recebimento = p_data_recebimento,
          status = COALESCE(p_status, 'pendente'),
          subtitle = p_subtitle,
          updated_at = NOW()
    WHERE id = p_existing_id
    RETURNING id INTO v_requisicao_id;

    IF v_requisicao_id IS NULL THEN
      INSERT INTO public.requisicoes (
        nome, solicitante, preparador, loja_solicitante, loja_preparadora,
        data_pedido, data_recebimento, status, subtitle
      ) VALUES (
        p_nome, p_solicitante, p_preparador, p_loja_solicitante, p_loja_preparadora,
        p_data_pedido, p_data_recebimento, COALESCE(p_status, 'pendente'), p_subtitle
      ) RETURNING id INTO v_requisicao_id;
    ELSE
      DELETE FROM public.requisicoes_itens WHERE requisicao_id = v_requisicao_id;
    END IF;
  ELSE
    INSERT INTO public.requisicoes (
      nome, solicitante, preparador, loja_solicitante, loja_preparadora,
      data_pedido, data_recebimento, status, subtitle
    ) VALUES (
      p_nome, p_solicitante, p_preparador, p_loja_solicitante, p_loja_preparadora,
      p_data_pedido, p_data_recebimento, COALESCE(p_status, 'pendente'), p_subtitle
    ) RETURNING id INTO v_requisicao_id;
  END IF;

  IF p_itens IS NOT NULL THEN
    FOR v_item IN SELECT jsonb_array_elements(p_itens) LOOP
      v_nome := COALESCE(NULLIF(TRIM(v_item->>'nome_produto'), ''), NULL);
      IF v_nome IS NULL THEN
        CONTINUE;
      END IF;
      v_qtd_solicitada := COALESCE((v_item->>'quantidade_solicitada')::INT, 0);
      v_qtd_enviada := COALESCE(v_item->>'quantidade_enviada', '');
      v_obs := COALESCE(v_item->>'observacao', '');
      v_ordem := COALESCE((v_item->>'ordem')::INT, 0);
      v_category := COALESCE(v_item->>'category', NULL);
      v_produto_id := COALESCE((v_item->>'produto_id')::INT, NULL);
      -- Novo: unidade_medida do item. Default 'cx' se nao vier.
      v_unidade := COALESCE(NULLIF(TRIM(v_item->>'unidade_medida'), ''), 'cx');

      INSERT INTO public.requisicoes_itens (
        requisicao_id, nome_produto, quantidade_solicitada, quantidade_enviada,
        observacao, ordem, category, produto_id, unidade_medida
      ) VALUES (
        v_requisicao_id, v_nome, v_qtd_solicitada, v_qtd_enviada, v_obs, v_ordem, v_category, v_produto_id, v_unidade
      );
    END LOOP;
  END IF;

  RETURN v_requisicao_id;
END;
$function$;

