const fetchQueue = useCallback(async () => {
  setLoading(true);
  await withTrace('logistica.fila.carregar', async () => {
    const startTime = performance.now();
    try {
      // PADRONIZADO: Usar os 3 status do banco diretamente (em_fila, em_progresso, finalizada)
      const selected = statusFilter.length
        ? statusFilter
        : ['em_fila', 'em_progresso', 'finalizada'];

      // Buscar requisições filtrando pelo campo status diretamente
      const { data: reqs, error } = await supabase
        .from('requisicoes')
        .select(
          `id, nome, solicitante, loja_solicitante, loja_preparadora, data_pedido, data_recebimento, created_at, status, user_id, subtitle, expedicao_id, requisicoes_itens(*)`,
        )
        .in('status', selected)
        .order('created_at', { ascending: false });

      if (error) throw error;
      const result = (reqs as any[]) || [];

      let filtered = result;
      if (lojaFilter !== 'todas') {
        const lojaName = (() => {
          const found = stores.find((s) => String(s.id) === String(lojaFilter));
          return found?.name || '';
        })();
        filtered = filtered.filter((r) => r.loja_solicitante === lojaName);
      }

      {
        const userIds = Array.from(
          new Set((filtered || []).map((r: any) => r.user_id).filter(Boolean)),
        );
        const namesMap: Record<string, string> = {};
